package receipt

import (
	"fmt"
	"strings"
)

// Line is one purchased item on a receipt.
type Line struct {
	Name  string
	Cents int
}

const currency = "USD"

const legacyWidth = 32

// Render prints each line and the total, one per row.
func Render(lines []Line) string {
	var rows []string
	total := 0
	for _, line := range lines {
		rows = append(rows, fmt.Sprintf("%s %s", line.Name, money(line.Cents)))
		total += line.Cents
	}
	rows = append(rows, fmt.Sprintf("TOTAL %s", money(total)))
	return strings.Join(rows, "\n")
}

func money(cents int) string {
	return fmt.Sprintf("%d.%02d", cents/100, cents%100)
}

func legacyMoney(cents int) string {
	return fmt.Sprintf("%s %d.%02d", currency, cents/100, cents%100)
}

func padRight(text string, width int) string {
	if len(text) >= width {
		return text
	}
	return text + strings.Repeat(" ", width-len(text))
}

