package receipt

import "testing"

func TestRenderListsLinesAndTotal(t *testing.T) {
	got := Render([]Line{{Name: "pen", Cents: 150}, {Name: "pad", Cents: 400}})
	want := "pen 1.50\npad 4.00\nTOTAL 5.50"
	if got != want {
		t.Fatalf("Render = %q, want %q", got, want)
	}
}
